def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    v = s.get('volume_per_atom_A3')
    if v is None or not isfinite(v) or v <= 0:
        return nan
    total = 0.0
    weight = 0.0
    for site in sites:
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        o = site.get('occupancy')
        o = 1.0 if o is None else o
        if r is not None and isfinite(r) and r > 0 and isfinite(o) and o > 0:
            total += o * r ** 3
            weight += o
    return float(4.0 * pi * total / (3.0 * weight * v)) if weight > 0 else nan

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    occ = [1.0 if t.get('occupancy') is None else t.get('occupancy') for t in sites]
    near = [inf for k in range(n)]
    for bond in s.get('neighbors') or []:
        i = bond.get('i')
        j = bond.get('j')
        d = bond.get('distance_A')
        if i is None or j is None or not 0 <= i < n or not 0 <= j < n:
            continue
        a, b = radii[i], radii[j]
        if a is None or b is None or not isfinite(a) or not isfinite(b) or a <= 0 or b <= 0:
            continue
        if d is not None and isfinite(d) and d > 0 and occ[j] > 0:
            near[i] = min(near[i], d / (a + b))
    w = sum(occ[i] for i in range(n) if isfinite(near[i]) and isfinite(occ[i]) and occ[i] > 0)
    return float(sum(occ[i] * near[i] for i in range(n) if isfinite(near[i]) and isfinite(occ[i]) and occ[i] > 0) / w) if w > 0 else nan

