def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    occ = [1.0 if t.get('occupancy') is None else t.get('occupancy') for t in sites]
    counts = {}
    for i in range(n):
        if isfinite(occ[i]) and occ[i] > 0:
            el = sites[i].get('element')
            counts[el] = counts.get(el, 0.0) + occ[i]
    z = sum(counts.values())
    if z <= 0:
        return nan
    expected = 1.0 - sum((v / z) ** 2 for v in counts.values())
    if expected <= 1e-12:
        return 0.0
    total = 0.0
    unlike = 0.0
    for bond in s.get('neighbors') or []:
        i, j = bond.get('i'), bond.get('j')
        d = bond.get('distance_A')
        if i is None or j is None or not 0 <= i < n or not 0 <= j < n:
            continue
        a, b = radii[i], radii[j]
        if a is None or b is None or not isfinite(a) or not isfinite(b) or a <= 0 or b <= 0:
            continue
        if d is None or not isfinite(d) or d <= 0 or occ[i] <= 0 or occ[j] <= 0:
            continue
        x = d / (1.25 * (a + b))
        if x < 2.5:
            w = occ[i] * occ[j] * exp(-(x ** 6))
            total += w
            if sites[i].get('element') != sites[j].get('element'):
                unlike += w
    return float(unlike / (total * expected)) if total > 0 else nan

